import * as React from 'react';
import * as AccordionPrimitive from '@radix-ui/react-accordion';
import { ChevronDown } from 'lucide-react';
import { cn } from '@/lib/utils';

/**
 * Accordion Component
 *
 * A vertically stacked set of interactive headings that each reveal a section of content.
 *
 * Based on Figma component: https://www.figma.com/design/nadcKNlrnZUHbbLwm9GdK4?node-id=2643:1487
 *
 * @see https://ui.shadcn.com/docs/components/accordion
 * @see https://www.radix-ui.com/docs/primitives/components/accordion
 *
 * @example
 * ```tsx
 * <Accordion type="single" collapsible>
 *   <AccordionItem value="item-1">
 *     <AccordionTrigger>What is a micro-interaction?</AccordionTrigger>
 *     <AccordionContent>
 *       Micro-interactions are events which have one main task — a single purpose — and they are found all over your device and within apps.
 *     </AccordionContent>
 *   </AccordionItem>
 * </Accordion>
 * ```
 */
const Accordion = AccordionPrimitive.Root;

const AccordionItem = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Item>
>(({ className, ...props }, ref) => (
  <AccordionPrimitive.Item
    ref={ref}
    className={cn('border-b border-border', className)}
    {...props}
  />
));
AccordionItem.displayName = 'AccordionItem';

const AccordionTrigger = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Trigger>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Header className="flex">
    <AccordionPrimitive.Trigger
      ref={ref}
      className={cn(
        'flex flex-1 items-center justify-between py-4 text-base font-medium transition-all hover:underline [&[data-state=open]>svg]:rotate-180',
        className
      )}
      {...props}
    >
      {children}
      <ChevronDown className="h-4 w-4 shrink-0 text-foreground transition-transform duration-200" />
    </AccordionPrimitive.Trigger>
  </AccordionPrimitive.Header>
));
AccordionTrigger.displayName = AccordionPrimitive.Trigger.displayName;

const AccordionContent = React.forwardRef<
  React.ElementRef<typeof AccordionPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof AccordionPrimitive.Content>
>(({ className, children, ...props }, ref) => (
  <AccordionPrimitive.Content
    ref={ref}
    className="overflow-hidden text-sm data-[state=closed]:animate-accordion-up data-[state=open]:animate-accordion-down"
    {...props}
  >
    <div className={cn('pb-4 pt-0', className)}>{children}</div>
  </AccordionPrimitive.Content>
));
AccordionContent.displayName = AccordionPrimitive.Content.displayName;

export { Accordion, AccordionItem, AccordionTrigger, AccordionContent };

export {
  Accordion,
  AccordionItem,
  AccordionTrigger,
  AccordionContent,
} from './Accordion';

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Utility function to merge class names
 * Combines clsx for conditional classes with tailwind-merge
 * to properly handle conflicting Tailwind classes
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* Design Tokens - Non-theme-specific tokens */
@import './design-tokens.css';

/* Theme Files */
@import './themes/light.css';
@import './themes/dark.css';
@import './themes/atxp.css';
@import './themes/dbg.css';

@import "tailwindcss";

@theme {
  /* Colors */
  --color-border: var(--theme-border);
  --color-border-hover: var(--theme-border-hover);
  --color-background: var(--theme-background);
  --color-foreground: var(--theme-foreground);
  --color-muted: var(--theme-muted);
  --color-muted-foreground: var(--theme-muted-foreground);
  --color-input: var(--theme-input);
  --color-ring: var(--theme-ring);

  --color-primary: var(--theme-primary);
  --color-primary-hover: var(--theme-primary-hover);
  --color-primary-foreground: var(--theme-primary-foreground);

  --color-secondary: var(--theme-secondary);
  --color-secondary-foreground: var(--theme-secondary-foreground);

  --color-accent: var(--theme-accent);
  --color-accent-hover: var(--theme-accent-hover);
  --color-accent-foreground: var(--theme-accent-foreground);
  --color-accent-muted: var(--theme-accent-muted);

  --color-card: var(--theme-card);
  --color-card-foreground: var(--theme-card-foreground);

  --color-popover: var(--theme-popover);
  --color-popover-foreground: var(--theme-popover-foreground);

  --color-destructive: var(--theme-destructive);
  --color-destructive-foreground: var(--theme-destructive-foreground);

  --color-success: var(--theme-success);
  --color-success-background: var(--theme-success-background-fill);

  --color-warning: var(--theme-warning);
  --color-warning-foreground: var(--theme-warning-foreground);
  --color-warning-alt: var(--theme-warning-alt);

  --color-info: var(--theme-info);
  --color-info-foreground: var(--theme-info-foreground);

  /* Border Radius */
  --radius-lg: var(--theme-radius);
  --radius-md: var(--radius-md);

  /* Font Family */
  --font-family-sans: var(--font-family-sans);

  /* Font Sizes */
  --font-size-xs: var(--font-size-xs);
  --font-size-sm: var(--font-size-sm);
  --font-size-base: var(--font-size-base);

  /* Font Weights */
  --font-weight-medium: var(--font-weight-medium);
  --font-weight-semibold: var(--font-weight-semibold);

  /* Animations */
  --animate-accordion-down: accordion-down 0.2s ease-out;
  --animate-accordion-up: accordion-up 0.2s ease-out;

  @keyframes accordion-down {
    from {
      height: 0;
    }
    to {
      height: var(--radix-accordion-content-height);
    }
  }

  @keyframes accordion-up {
    from {
      height: var(--radix-accordion-content-height);
    }
    to {
      height: 0;
    }
  }
}

@layer base {
  * {
    border-color: var(--theme-border);
  }

  body {
    background-color: var(--theme-background);
    color: var(--theme-foreground);
    font-family: var(--font-family-sans);
  }

  /* Custom Scrollbar Styling */
  /* Based on Figma: https://www.figma.com/design/nadcKNlrnZUHbbLwm9GdK4?node-id=2823-2148 */

  /* Firefox */
  * {
    scrollbar-width: thin;
    scrollbar-color: var(--theme-primary) var(--theme-muted);
  }

  /* Webkit browsers (Chrome, Safari, Edge) */
  *::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }

  *::-webkit-scrollbar-track {
    background: var(--theme-muted);
    border-radius: 10px;
  }

  *::-webkit-scrollbar-thumb {
    background: var(--theme-primary);
    border-radius: 10px;
    border: 2px solid var(--theme-muted);
  }

  *::-webkit-scrollbar-thumb:hover {
    background: var(--theme-primary-hover);
  }

  *::-webkit-scrollbar-corner {
    background: var(--theme-muted);
  }
}

/**
 * Design Tokens
 * Non-theme-specific design system tokens
 *
 * From Figma Design System
 * https://www.figma.com/design/nadcKNlrnZUHbbLwm9GdK4/C-C-Design-System---Components
 */

:root {
  /* Colors - Purple Scale */
  --color-purple-600: #9810fa;

  /* Typography - Font Family */
  --font-family-sans: Inter, sans-serif;

  /* Typography - Font Sizes */
  --font-size-xs: 12px;
  --font-size-sm: 14px;
  --font-size-base: 16px;

  /* Typography - Font Weights */
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Typography - Line Heights */
  --font-leading-4: 16px;
  --font-leading-5: 20px;
  --font-leading-6: 24px;

  /* Typography - Letter Spacing */
  --font-tracking-normal: 0px;

  /* Spacing Scale */
  --spacing-0-5: 2px;
  --spacing-2: 8px;
  --spacing-3-5: 14px;
  --spacing-4: 16px;
  --spacing-5: 20px;
  --spacing-6: 24px;
  --spacing-8: 32px;

  /* Border Radius */
  --theme-radius: 8px;
  --radius-md: 6px;
  --radius-2xl: 16px;

  /* Border Width */
  --border-width-1: 1px;
  --border-width-2: 2px;

  /* Opacity */
  --opacity-80: 0.8;
  --opacity-100: 1;
}

/**
 * Light Theme (Primary/Default)
 * Figma: node-id=4800-7262
 * https://www.figma.com/design/nadcKNlrnZUHbbLwm9GdK4/C-C-Design-System---Components
 */

:root {
  /* Base Colors */
  --theme-foreground: #020618;
  --theme-background: #ffffff;
  --theme-muted: #f1f5f9;
  --theme-muted-foreground: #62748e;
  --theme-border: #bebcfc;
  --theme-border-hover: #9e9afb;
  --theme-input: #e2e8f0;
  --theme-ring: #020618;

  /* Primary Colors */
  --theme-primary: #5d57f8;
  --theme-primary-hover: #5751e2;
  --theme-primary-foreground: #f8fafc;

  /* Secondary Colors */
  --theme-secondary: #f1f5f9;
  --theme-secondary-foreground: #314158;

  /* Accent Colors */
  --theme-accent: #efeefe;
  --theme-accent-hover: #dfddfe;
  --theme-accent-foreground: #0f172b;
  --theme-accent-muted: #beeaec;

  /* Card */
  --theme-card: #ffffff;
  --theme-card-foreground: #020618;

  /* Popover */
  --theme-popover: #ffffff;
  --theme-popover-foreground: #020618;

  /* Semantic Colors */
  --theme-destructive: #e7000b;
  --theme-destructive-foreground: #f8fafc;

  --theme-success: #2a9d90;
  --theme-success-background-fill: #ecfdf5;

  --theme-warning: #e76e50;
  --theme-warning-foreground: #f8fafc;
  --theme-warning-alt: #e8c468;

  --theme-info: #5dcbcf;
  --theme-info-foreground: #f8fafc;

  /* Chart Colors */
  --theme-chart-1: #e76e50;
  --theme-chart-2: #2a9d90;
  --theme-chart-3: #274754;
  --theme-chart-4: #e8c468;
  --theme-chart-5: #f4a462;

  /* Sidebar */
  --theme-sidebar-background: #f8fafc;
  --theme-sidebar-foreground: #314158;
  --theme-sidebar-primary: #0f172b;
  --theme-sidebar-primary-foreground: #f8fafc;
  --theme-sidebar-accent: #f1f5f9;
  --theme-sidebar-accent-foreground: #0f172b;
  --theme-sidebar-border: #bebcfc;
}

/**
 * Dark Theme
 * Optimized for low-light environments
 */

[data-theme="dark"] {
  /* Base Colors */
  --theme-foreground: #f8fafc;
  --theme-background: #020618;
  --theme-muted: #1e293b;
  --theme-border: #4c4799;

  /* Primary Colors */
  --theme-primary: #7c77ff;
  --theme-primary-foreground: #020618;

  /* Secondary Colors */
  --theme-secondary: #1e293b;
  --theme-secondary-foreground: #cbd5e1;

  /* Semantic Colors */
  --theme-destructive: #ff4757;
  --theme-destructive-foreground: #f8fafc;

  --theme-success: #10d9a0;
  --theme-success-background-fill: #0a3329;

  --theme-warning: #ff6b6b;
  --theme-warning-foreground: #f8fafc;
  --theme-warning-alt: #ffd93d;

  --theme-info: #7ddee0;
  --theme-info-foreground: #020618;

  /* Muted Colors */
  --theme-muted-foreground: #334155;
  --theme-accent-muted: #1a3538;

  /* Accent */
  --theme-accent: #1e293b;
  --theme-accent-hover: #2d3f5f;
  --theme-accent-foreground: #f8fafc;

  /* Card */
  --theme-card: #0f172a;
  --theme-card-foreground: #f8fafc;

  /* Popover */
  --theme-popover: #0f172a;
  --theme-popover-foreground: #f8fafc;

  /* Input */
  --theme-input: #334155;
  --theme-ring: #7c77ff;

  /* Border Hover */
  --theme-border-hover: #6b66ff;

  /* Primary Hover */
  --theme-primary-hover: #6b66ff;

  /* Chart Colors */
  --theme-chart-1: #ff6b6b;
  --theme-chart-2: #10d9a0;
  --theme-chart-3: #4a5f7a;
  --theme-chart-4: #ffd93d;
  --theme-chart-5: #ff9f43;

  /* Sidebar */
  --theme-sidebar-background: #0f172a;
  --theme-sidebar-foreground: #cbd5e1;
  --theme-sidebar-primary: #f8fafc;
  --theme-sidebar-primary-foreground: #020618;
  --theme-sidebar-accent: #1e293b;
  --theme-sidebar-accent-foreground: #f8fafc;
  --theme-sidebar-border: #4c4799;
}

/**
 * Automatic Dark Mode
 * Applies dark theme when user's system preference is dark
 * Only applies if no explicit data-theme is set
 */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    /* Base Colors */
    --theme-foreground: #f8fafc;
    --theme-background: #020618;
    --theme-muted: #1e293b;
    --theme-border: #4c4799;

    /* Primary Colors */
    --theme-primary: #7c77ff;
    --theme-primary-foreground: #020618;

    /* Secondary Colors */
    --theme-secondary: #1e293b;
    --theme-secondary-foreground: #cbd5e1;

    /* Semantic Colors */
    --theme-destructive: #ff4757;
    --theme-destructive-foreground: #f8fafc;

    --theme-success: #10d9a0;
    --theme-success-background-fill: #0a3329;

    --theme-warning: #ff6b6b;
    --theme-warning-foreground: #f8fafc;
    --theme-warning-alt: #ffd93d;

    --theme-info: #7ddee0;
    --theme-info-foreground: #020618;

    /* Muted Colors */
    --theme-muted-foreground: #334155;
    --theme-accent-muted: #1a3538;

    /* Accent */
    --theme-accent: #1e293b;
    --theme-accent-hover: #2d3f5f;
    --theme-accent-foreground: #f8fafc;

    /* Card */
    --theme-card: #0f172a;
    --theme-card-foreground: #f8fafc;

    /* Popover */
    --theme-popover: #0f172a;
    --theme-popover-foreground: #f8fafc;

    /* Input */
    --theme-input: #334155;
    --theme-ring: #7c77ff;

    /* Border Hover */
    --theme-border-hover: #6b66ff;

    /* Primary Hover */
    --theme-primary-hover: #6b66ff;

    /* Chart Colors */
    --theme-chart-1: #ff6b6b;
    --theme-chart-2: #10d9a0;
    --theme-chart-3: #4a5f7a;
    --theme-chart-4: #ffd93d;
    --theme-chart-5: #ff9f43;

    /* Sidebar */
    --theme-sidebar-background: #0f172a;
    --theme-sidebar-foreground: #cbd5e1;
    --theme-sidebar-primary: #f8fafc;
    --theme-sidebar-primary-foreground: #020618;
    --theme-sidebar-accent: #1e293b;
    --theme-sidebar-accent-foreground: #f8fafc;
    --theme-sidebar-border: #4c4799;
  }
}

/**
