  --theme-input: #e2e8f0;
  --theme-ring: #020618;

  /* Primary Colors - Black */
  --theme-primary: #000000;
  --theme-primary-hover: #0f172b;
  --theme-primary-foreground: #f8fafc;

  /* Secondary Colors */
